from sentence_transformers import SentenceTransformer

model = SentenceTransformer('intfloat/multilingual-e5-base')

def embed_passage(text: str):
    return model.encode(f"passage: {text}", normalize_embeddings=True)

def embed_query(text: str):
    return model.encode(f"query: {text}", normalize_embeddings=True)

def check(user, pwd, coll, op):
    try:
        c = MilvusClient(uri="http://localhost:19530",
                         user=user, password=pwd)
        if op == "search":
            c.search(collection_name=coll,
                     data=[[0.0]*768], limit=1)
        elif op == "insert":
            c.insert(collection_name=coll, data=[{}])
        return "OK"

⛔ БЫЛО: в проверке используются «нулевой» вектор и пустой словарь. Пустой словарь insert вызывает ошибку валидации данных (нет обязательных полей) независимо от прав, поэтому результат «DENIED» в таблице ниже не подтверждает разграничение доступа. Нулевой вектор Milvus, напротив, принимает без ошибки (проверено ✔).
